begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir helpers/phase10_fixtures.sql
create temp table p10_state(key text primary key,value uuid);
grant all on p10_state to authenticated,service_role;
select ok(not has_table_privilege('authenticated','public.payment_invoices','INSERT'),'browser cannot write invoices');
select ok(not has_table_privilege('authenticated','public.payment_observations','INSERT'),'browser cannot forge verification');
select ok(not has_table_privilege('anon','public.payment_transactions','SELECT'),'anonymous cannot see transactions');
select ok(not has_function_privilege('authenticated','public.payment_record_test_observation(uuid,uuid,uuid,text,text,text)','EXECUTE'),'verification recorder is service only');
select ok(not has_function_privilege('anon','public.admin_create_test_payment_invoice(uuid,uuid,text,text,text,text)','EXECUTE'),'anonymous cannot create invoices');
select ok(not has_function_privilege('authenticated','public.payment_get_test_snapshot(uuid)','EXECUTE'),'browser cannot read independent provider fixture');
select is((select count(*) from private.payment_adapter_registry),2::bigint,'both test channels registered');
select is((select count(*) from private.agent_tool_registry),7::bigint,'AI money tools are not enabled');
set local role authenticated;
select set_config('request.jwt.claim.sub','d3100000-0000-4000-8000-000000000001',true);
insert into p10_state values('crypto',public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','external_crypto','USDT','79000000','crypto-key'));
insert into p10_state values('stars',public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','telegram_stars','XTR','100','stars-key'));
select is(public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','external_crypto','USDT','79000000','crypto-key'),(select value from p10_state where key='crypto'),'invoice creation is idempotent');
select throws_ok($$select public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','external_crypto','USDT','79000001','crypto-key')$$,'23505','payment idempotency conflict','conflicting amount under existing key is rejected');
select throws_ok($$select public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000002','d3600000-0000-4000-8000-000000000001','external_crypto','USDT','79000000','other')$$,'42501','payment test permission denied','cross-tenant invoice creation denied');
select throws_ok($$select public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','telegram_stars','USDT','100','wrong-asset')$$,'22023','test asset channel not approved','crypto cannot replace Stars on Telegram surface');
select throws_ok($$select public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','external_crypto','BTC','100','unapproved')$$,'22023','test asset channel not approved','assets require explicit approval rules');
select throws_ok($$select public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','external_crypto','USDT','1e6','invalid')$$,'22023','test invoice input invalid','ambiguous numeric format rejected');
select is((select amount_units::text from public.payment_invoices where id=(select value from p10_state where key='crypto')),'79000000','atomic amount preserved exactly');
select is((select surface from public.payment_invoices where id=(select value from p10_state where key='crypto')),'independent_web','crypto has independent web provenance');
select is((select surface from public.payment_invoices where id=(select value from p10_state where key='stars')),'telegram_bot','Stars retains Telegram provenance');
select is(jsonb_array_length(public.admin_payment_list('d3200000-0000-4000-8000-000000000001')),2,'unified admin lists both channels');
select throws_ok($$select public.admin_payment_list('d3200000-0000-4000-8000-000000000002')$$,'42501','payment read denied','admin read is tenant scoped');
insert into p10_state values('pending',public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),'insufficient_confirmations','p1'));
select is(public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),'insufficient_confirmations','p1'),(select value from p10_state where key='pending'),'provider simulation is idempotent');
select throws_ok($$select public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),'settled','p1')$$,'23505','simulation idempotency conflict','provider event cannot change scenario');
insert into p10_state values('settled',public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),'settled','p2'));
insert into p10_state values('stars-settled',public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='stars'),'settled','s1'));
reset role;
set local role service_role;
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),(select value from p10_state where key='pending'),'test:event:pending',repeat('a',64),'webhook')->>'state','PENDING','insufficient crypto confirmations stay pending');
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),(select value from p10_state where key='settled'),'test:event:settled',repeat('b',64),'webhook')->>'state','CONFIRMED','independent settled provider evidence confirms simulation');
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),(select value from p10_state where key='settled'),'test:event:settled',repeat('b',64),'webhook')->>'duplicate','true','duplicate webhook is acknowledged without repeating effects');
select throws_ok($$select public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),(select value from p10_state where key='settled'),'test:event:settled',repeat('c',64),'webhook')$$,'23505','payment event content conflict','same provider event with changed raw body is rejected');
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),(select value from p10_state where key='pending'),'test:event:old',repeat('d',64),'reconcile')->>'reason','STALE_EVIDENCE_RETAINED','old evidence cannot undo a newer confirmation');
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='stars'),(select value from p10_state where key='stars-settled'),'test:event:stars',repeat('e',64),'webhook')->>'state','CONFIRMED','Stars interface uses the same confirmation ledger');
select throws_ok($$select public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='stars'),(select value from p10_state where key='settled'),'test:event:wrong',repeat('f',64),'webhook')$$,'42501','test evidence scope denied','evidence cannot cross invoices or channels');
reset role;
select is((select count(*) from public.payment_transactions where tenant_id='d3200000-0000-4000-8000-000000000001'),2::bigint,'one transaction reference per payment');
select is((select count(*) from public.payment_observations where tenant_id='d3200000-0000-4000-8000-000000000001'),4::bigint,'duplicate receipt did not create history');
select is((select count(*) from public.audit_logs where tenant_id='d3200000-0000-4000-8000-000000000001' and action='payment.test_evidence_recorded'),4::bigint,'verification and audit commit together');
select is((select count(*) from public.domain_events where tenant_id='d3200000-0000-4000-8000-000000000001' and event_type='payment.test_observed'),4::bigint,'only distinct test observation events emitted');
select is((select count(*) from public.domain_events where tenant_id='d3200000-0000-4000-8000-000000000001' and event_type='payment.confirmed'),0::bigint,'test evidence cannot emit a real confirmation');
select is((select state::text from public.customers where id='d3300000-0000-4000-8000-000000000001'),'NEW','customer lifecycle unchanged by simulated payments');
select is((select count(*) from public.messages where tenant_id='d3200000-0000-4000-8000-000000000001' and direction='outbound'),0::bigint,'no Telegram invoice or message sent');
select ok(to_regclass('public.subscriptions') is null,'no subscription implementation');
select ok(to_regclass('public.channel_access') is null,'no VIP granting implementation');
select throws_ok($$update public.payment_invoices set mode='live' where id=(select value from p10_state where key='crypto')$$,'42501','invoice snapshot immutable','test invoice cannot turn into a real payment');
select throws_ok($$update public.payment_invoices set amount_units=1 where id=(select value from p10_state where key='crypto')$$,'42501','invoice snapshot immutable','quote amount cannot be silently rewritten');
select throws_ok($$delete from public.payment_observations where tenant_id='d3200000-0000-4000-8000-000000000001'$$,'42501','payment history immutable','provider evidence history is append only');
select throws_ok($$update private.payment_test_snapshots set snapshot='{}' where id=(select value from p10_state where key='settled')$$,'42501','payment history immutable','independent test snapshot cannot be edited');
set local role authenticated;
select set_config('request.jwt.claim.sub','d3100000-0000-4000-8000-000000000002',true);
select is(jsonb_array_length(public.admin_payment_list('d3200000-0000-4000-8000-000000000001')),2,'support can inspect payment evidence');
select throws_ok($$select public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='stars'),'settled','support')$$,'42501','payment test permission denied','support cannot fabricate simulations');
select set_config('request.jwt.claim.sub','d3100000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.payment_invoices),0::bigint,'readonly role cannot see payment rows');
select throws_ok($$select public.admin_payment_list('d3200000-0000-4000-8000-000000000001')$$,'42501','payment read denied','readonly cannot bypass payment policy by RPC');
reset role;
-- Each mismatch runs on a new invoice, so review hold does not mask classification.
do $$declare scenario text;i uuid;s uuid;expected_state text;result jsonb;begin
 perform set_config('request.jwt.claim.sub','d3100000-0000-4000-8000-000000000001',true);
 foreach scenario in array array['underpaid','overpaid','wrong_asset','wrong_network','wrong_recipient','late','failed','refunded','reorg'] loop
  i:=public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','external_crypto','USDC','79000000','scenario-'||scenario);
  s:=public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',i,scenario,'case');
  result:=public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',i,s,'test:case:'||scenario,repeat('a',64),'reconcile');
  expected_state:=case scenario when 'failed' then 'FAILED' when 'refunded' then 'REFUNDED' else 'REVIEW' end;
  if result->>'state'<>expected_state then raise exception 'scenario %: unexpected result %',scenario,result;end if;
 end loop;
end;$$;
select is((select count(*) from public.payment_invoices where idempotency_key like 'scenario-%'),9::bigint,'all mismatch/finality/terminal cases run independently');
select is((select status from public.payment_invoices where idempotency_key='scenario-underpaid'),'REVIEW','underpayment is held');
select is((select status from public.payment_invoices where idempotency_key='scenario-wrong_network'),'REVIEW','wrong chain cannot confirm');
select is((select status from public.payment_invoices where idempotency_key='scenario-reorg'),'REVIEW','chain reorg is held');
-- Provider transfer reuse is tested across two independent invoice references.
insert into p10_state values('duplicate-invoice',public.admin_create_test_payment_invoice('d3200000-0000-4000-8000-000000000001','d3600000-0000-4000-8000-000000000001','external_crypto','USDT','79000000','duplicate-transfer'));
insert into private.payment_test_snapshots(id,tenant_id,invoice_id,request_key,scenario,snapshot)
select 'd3700000-0000-4000-8000-000000000001',tenant_id,(select value from p10_state where key='duplicate-invoice'),'provider-transfer-reused','settled',snapshot||jsonb_build_object('id','d3700000-0000-4000-8000-000000000001','invoice_id',(select value from p10_state where key='duplicate-invoice'),'provider_reference','test:'||(select value::text from p10_state where key='duplicate-invoice')) from private.payment_test_snapshots where id=(select value from p10_state where key='settled');
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='duplicate-invoice'),'d3700000-0000-4000-8000-000000000001','test:reused-transfer',repeat('a',64),'reconcile')->>'reason','DUPLICATE_TRANSACTION','one provider transfer cannot pay a second invoice');
select is((select status from public.payment_invoices where id=(select value from p10_state where key='crypto')),'CONFIRMED','duplicate-transfer attempt does not disturb original confirmed invoice');
insert into p10_state values('held-settlement',public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select id from public.payment_invoices where idempotency_key='scenario-underpaid'),'settled','settled-after-hold'));
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select id from public.payment_invoices where idempotency_key='scenario-underpaid'),(select value from p10_state where key='held-settlement'),'test:held:settlement',repeat('a',64),'reconcile')->>'reason','REVIEW_HOLD','later settlement cannot release a review hold');
insert into p10_state values('refund',public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='stars'),'refunded','refund'));
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='stars'),(select value from p10_state where key='refund'),'test:stars:refund',repeat('a',64),'reconcile')->>'state','REFUNDED','verified provider refund changes a confirmed simulation');
insert into p10_state values('reorg',public.admin_simulate_test_payment('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),'reorg','reorg'));
select is(public.payment_record_test_observation('d3200000-0000-4000-8000-000000000001',(select value from p10_state where key='crypto'),(select value from p10_state where key='reorg'),'test:crypto:reorg',repeat('a',64),'reconcile')->>'state','REVIEW','chain reorg holds a previously confirmed simulation');
select finish();
rollback;
